import{_ as e,o,c as r,a2 as c}from"./chunks/framework.XctAhZuT.js";const h=JSON.parse('{"title":"导入课程包","description":"外部课程通过 .turnapack 进入 Turna。LibreLingo 等社区课程的 YAML 源在离线工具中转换成 .turnapack 后，即可像内置课程一样学习、复习和管理。","frontmatter":{"description":"外部课程通过 .turnapack 进入 Turna。LibreLingo 等社区课程的 YAML 源在离线工具中转换成 .turnapack 后，即可像内置课程一样学习、复习和管理。"},"headers":[],"relativePath":"guide/course-pack.md","filePath":"guide/course-pack.md","lastUpdated":1790697640000}'),i={name:"guide/course-pack.md"};function t(l,a,d,n,u,s){return o(),r("div",null,[...a[0]||(a[0]=[c('<h1 id="导入课程包" tabindex="-1">导入课程包 <a class="header-anchor" href="#导入课程包" aria-label="Permalink to &quot;导入课程包&quot;">​</a></h1><p>外部课程通过 <code>.turnapack</code> 进入 Turna。LibreLingo 等社区课程的 YAML 源在离线工具中转换成 <code>.turnapack</code> 后，即可像内置课程一样学习、复习和管理。</p><p>包有两个版本：<code>turnapack/1</code> 是单个 JSON 文件（无媒体），<code>turnapack/2</code> 是带 <code>media/</code> 的压缩包。手工制作的纯 JSON 内容可以用 <code>.json</code> 扩展名导入，格式契约见<a href="/docs/authoring/course-pack">外部课程包</a>。</p><div class="info custom-block"><p class="custom-block-title">没有内置课程商店</p><p>应用不提供在线下载。<code>.turnapack</code> 文件需要自行转换（见<a href="/docs/authoring/course-pack">外部课程包</a>）或从他人处获得，再手动导入。</p></div><h2 id="导入步骤" tabindex="-1">导入步骤 <a class="header-anchor" href="#导入步骤" aria-label="Permalink to &quot;导入步骤&quot;">​</a></h2><ol><li>在学习页顶栏点击地球图标，进入「课程管理」。</li><li>滚动到底部「添加课程」区，点击「导入课程包」。</li><li>在文件选择器中选择 <code>.turnapack</code> 文件（手工制作的纯 JSON 包也可以是 <code>.json</code>）。</li><li>等待进度走完：解析课程包 → 校验课程内容 → 写入课程库。</li><li>成功提示会显示课程名、章节数与词条数，新课程随即出现在课程列表中。</li></ol><p>导入包的 <code>language.code</code> 决定它在课程列表中的身份：两位或三位小写字母，且<strong>不能占用内置课程的语言码</strong>，也不能是保留字 <code>anki</code>。</p><h2 id="重复导入与覆盖确认" tabindex="-1">重复导入与覆盖确认 <a class="header-anchor" href="#重复导入与覆盖确认" aria-label="Permalink to &quot;重复导入与覆盖确认&quot;">​</a></h2><p>对已安装的语言再次导入时，应用先弹出「替换现有课程？」确认：</p><ul><li>新包中<strong>仍然存在</strong>的词条与内容，学习进度保留。</li><li>新包中<strong>被移除</strong>的内容，其复习进度、错题等记录一并清除。</li><li>点「取消」则不写入任何内容。</li></ul><p>取消确认属于正常退出，不算导入失败。</p><h2 id="卸载与恢复" tabindex="-1">卸载与恢复 <a class="header-anchor" href="#卸载与恢复" aria-label="Permalink to &quot;卸载与恢复&quot;">​</a></h2><ul><li>在课程管理页可移除导入的课程，移除前需确认。</li><li>移除后语言出现在「已卸载的语言」区，可随时点「恢复」——应用保留了当时导入的 <code>.turnapack</code> 副本，恢复时重新解包播种，无需再找原文件。</li><li>如果保留的包文件不可用（例如系统清理了应用数据），会提示「无法恢复，需重新导入课程包」。</li></ul><h2 id="备份边界" tabindex="-1">备份边界 <a class="header-anchor" href="#备份边界" aria-label="Permalink to &quot;备份边界&quot;">​</a></h2><p>备份覆盖课程数据库（含导入课程的学习记录与语言元信息），<strong>不覆盖</strong> <code>.turnapack</code> 包文件本身。换设备或清除应用数据后，需要重新执行一次导入。建议把原始 <code>.turnapack</code> 文件放在应用之外的备份位置，见<a href="/docs/guide/data-and-privacy#备份原则">本地数据与隐私</a>。</p><h2 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h2><ul><li>导入课程的内容在应用内只读；不能用桌面课程编辑器修改，需要改动时重新生成并覆盖导入。</li><li>包内媒体（图片 / 音频）随导入解压到应用私有目录，仅在删除课程时清理。</li><li>没有音频媒体的包使用 TTS 朗读听力题，效果取决于设备 TTS 对目标语言的支持。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/authoring/course-pack">外部课程包（.turnapack）</a>：格式契约与 LibreLingo 转换工具</li><li><a href="/docs/guide/curriculum">课程结构</a></li><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li></ul>',19)])])}const k=e(i,[["render",t]]);export{h as __pageData,k as default};
